const valid=v=>typeof v==='number'&&Number.isFinite(v),fmt=(v,n=1)=>valid(v)?v.toLocaleString('pl-PL',{minimumFractionDigits:n,maximumFractionDigits:n}):'—',mean=vs=>{vs=vs.filter(valid);return vs.length?vs.reduce((a,b)=>a+b,0)/vs.length:null;},sum=vs=>{vs=vs.filter(valid);return vs.length?vs.reduce((a,b)=>a+b,0):null;},min=vs=>{vs=vs.filter(valid);return vs.length?Math.min(...vs):null;},max=vs=>{vs=vs.filter(valid);return vs.length?Math.max(...vs):null;};
const localDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Warsaw',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());let today=localDate();const dateLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('pl-PL',{day:'numeric',month:'long'}),fullLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('pl-PL',{weekday:'long',day:'numeric',month:'long',year:'numeric'}),dateShort=d=>d.slice(8,10)+'.'+d.slice(5,7),dayLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('pl-PL',{weekday:'short'}),runLabel=t=>new Date(t).toLocaleString('pl-PL',{timeZone:'UTC',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})+' UTC';
$('#today-label').textContent=fullLabel(today);$('#copyright-year').textContent=new Date().getFullYear();$('#menu-toggle').addEventListener('click',()=>{const open=$('#mobile-nav').hidden;$('#mobile-nav').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#menu-toggle').setAttribute('aria-label',open?'Zamknij menu':'Otwórz menu');});document.addEventListener('click',e=>{document.querySelectorAll('.nav-dropdown[open]').forEach(d=>{if(!d.contains(e.target))d.removeAttribute('open');});});
