let radarMeta=null,radarMetaAt=0,radarCleanup=null;
async function initRegionalRadar(){
 const container=$('#mk-radar-map');if(!container)return;
 if(radarCleanup)radarCleanup();let alive=true,map=null,layers=new Map(),current=null,frames=[],host='',index=0,busy=false,playing=false,playTimer=null,refreshTimer=null,frameToken=0;
 const status=$('#mk-radar-status'),time=$('#mk-radar-time'),select=$('#mk-radar-frame'),play=$('#mk-radar-play'),refresh=$('#mk-radar-refresh');
 const stamp=t=>new Date(t*1000).toLocaleString('pl-PL',{timeZone:'Europe/Warsaw',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
 function stop(){playing=false;clearTimeout(playTimer);play.textContent='▶ Odtwórz';play.setAttribute('aria-pressed','false');}
 function cleanup(){alive=false;stop();clearInterval(refreshTimer);document.removeEventListener('visibilitychange',visibility);if(map)map.remove();}
 function visibility(){if(document.hidden)stop();}
 radarCleanup=cleanup;document.addEventListener('visibilitychange',visibility);
 function schedule(){if(playing&&alive)playTimer=setTimeout(async()=>{if(!document.hidden)await show((index+1)%frames.length);else stop();schedule();},1800);}
 async function show(next){
  if(!alive||busy||!frames.length)return;busy=true;index=Math.max(0,Math.min(frames.length-1,next));select.value=String(index);const frame=frames[index],token=++frameToken;
  time.textContent='Czas klatki: '+stamp(frame.time)+' · czas polski';status.textContent='Pobieranie obrazu radarowego…';
  let layer=layers.get(frame.path);if(!layer){layer=window.L.tileLayer(host+frame.path+'/512/{z}/{x}/{y}/2/1_0.png',{tileSize:512,zoomOffset:-1,minZoom:5,maxZoom:10,maxNativeZoom:8,opacity:+$('#mk-radar-opacity').value/100,keepBuffer:0,updateWhenIdle:true,updateWhenZooming:false,attribution:'Weather data by <a href="https://www.rainviewer.com/" target="_blank" rel="noopener">RainViewer</a>'});layers.set(frame.path,layer);}
  const previous=current;let errors=0;
  const outcome=await new Promise(resolve=>{let finished=false;const done=()=>{if(finished)return;finished=true;clearTimeout(timeout);layer.off('load',done);layer.off('tileerror',error);resolve(errors===0);};const error=()=>{errors++;};const timeout=setTimeout(()=>{errors++;done();},15000);layer.once('load',done);layer.on('tileerror',error);layer.setOpacity(+$('#mk-radar-opacity').value/100);if(map.hasLayer(layer)){done();}else layer.addTo(map);});
  if(!alive||token!==frameToken)return;current=layer;layer.bringToFront();if(previous&&previous!==layer&&map.hasLayer(previous))map.removeLayer(previous);busy=false;
  const old=Date.now()/1000-frame.time>1800;
  status.textContent=!outcome?'Nie udało się pobrać części obrazu. Pusta mapa nie potwierdza braku opadu.':(old?'Starsza klatka — sprawdź jej godzinę. ':'')+'Klatka '+(index+1)+' z '+frames.length+' · obrazy historyczne';
  if(!outcome)stop();
 }
 async function update(force=false){
  if(!alive||busy)return;refresh.disabled=true;stop();const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);
  try{
   let data=radarMeta;if(force||!data||Date.now()-radarMetaAt>300000){const response=await fetch('https://api.rainviewer.com/public/weather-maps.json',{signal:controller.signal});if(!response.ok)throw Error('Radar metadata unavailable');data=await response.json();const url=new URL(data.host);if(url.protocol!=='https:'||!(url.hostname==='rainviewer.com'||url.hostname.endsWith('.rainviewer.com')))throw Error('Unexpected radar host');radarMeta=data;radarMetaAt=Date.now();}
   const past=Array.isArray(data.radar?.past)?data.radar.past.filter(f=>Number.isFinite(f.time)&&typeof f.path==='string'&&/^\/v2\/radar\/[a-zA-Z0-9_-]+$/.test(f.path)).sort((a,b)=>a.time-b.time):[];
   if(!past.length)throw Error('No radar frames');if(!alive)return;
   frames=past.slice(-13);host=data.host.replace(/\/$/,'');select.innerHTML=frames.map((f,i)=>'<option value="'+i+'">'+stamp(f.time)+(i===frames.length-1?' · najnowsza':'')+'</option>').join('');select.disabled=false;play.disabled=frames.length<2;await show(frames.length-1);
  }catch(error){if(alive)status.textContent='Radar chwilowo niedostępny. Użyj przycisku Odśwież radar lub otwórz mapę IMGW poniżej.';}
  finally{clearTimeout(timer);if(alive)refresh.disabled=false;}
 }
 try{
  const L=await loadLeaflet();if(!alive||!container.isConnected)return;container.innerHTML='';map=L.map(container,{scrollWheelZoom:false,minZoom:5,maxZoom:10}).setView([49.69,21.77],8);
  L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);
  L.circleMarker([49.69,21.77],{radius:5,color:'#0b3c66',weight:2,fillColor:'#fff',fillOpacity:1}).addTo(map).bindTooltip('Krosno',{permanent:true,direction:'right'});
  map.on('dragstart zoomstart',stop);
  select.onchange=()=>{stop();if(busy){select.value=String(index);return;}show(+select.value);};
  play.onclick=()=>{if(playing){stop();return;}if(busy)return;playing=true;play.textContent='❚❚ Zatrzymaj';play.setAttribute('aria-pressed','true');schedule();};
  $('#mk-radar-latest').onclick=()=>{stop();show(frames.length-1);};refresh.onclick=()=>update(true);$('#mk-radar-center').onclick=()=>{stop();map.setView([49.69,21.77],8);};
  $('#mk-radar-opacity').oninput=e=>{if(current)current.setOpacity(+e.target.value/100);$('#mk-radar-opacity-value').textContent=e.target.value+'%';};
  await update();refreshTimer=setInterval(()=>{if(alive&&container.isConnected&&!document.hidden&&!playing&&!busy)update();},300000);
 }catch(error){if(alive){container.innerHTML='<p class="empty">Nie udało się wczytać mapy.</p>';status.textContent='Radar chwilowo niedostępny. Odnośniki do zewnętrznych map są dostępne poniżej.';}}
}
function regionalRadarCard(){return '<section class="card feature-section" aria-labelledby="mk-radar-title"><div class="card-title"><div><div class="eyebrow">Krosno i okolice · obserwacje radarowe</div><h2 id="mk-radar-title">Radar opadów</h2></div><span class="pill">RainViewer</span></div><div class="toolbar"><button class="btn primary" id="mk-radar-play" disabled aria-pressed="false">▶ Odtwórz</button><button class="btn" id="mk-radar-latest">Najnowsza klatka</button><button class="btn" id="mk-radar-refresh">Odśwież radar</button><button class="btn" id="mk-radar-center">Wróć do Krosna</button></div><div class="toolbar"><label for="mk-radar-frame">Termin radaru · czas polski<select id="mk-radar-frame" disabled><option>Ładowanie terminów…</option></select></label><label for="mk-radar-opacity">Widoczność opadu <span id="mk-radar-opacity-value">70%</span><input id="mk-radar-opacity" type="range" min="10" max="100" step="5" value="70"></label></div><p id="mk-radar-time"><strong>Ładowanie czasu klatki…</strong></p><p id="mk-radar-status" class="small-note" role="status" aria-live="polite">Pobieranie radaru…</p><div id="mk-radar-map" role="region" aria-label="Mapa radarowa opadów wokół Krosna" style="height:420px;max-width:640px;width:100%;margin:12px auto;border-radius:12px;overflow:hidden;background:#e7eff4"><p class="empty">Ładowanie mapy…</p></div><p class="small-note">Animacja obejmuje dostępne obrazy z ostatnich około 2 godzin, zwykle co 10 minut. To obserwacje historyczne, bez prognozy ruchu opadów. Barwy pokazują odbiciowość radarową; nie są pomiarem sumy opadu przy gruncie. Czas klatki oznacza czas utworzenia mozaiki, której radary mogą mieć różne czasy pomiaru.</p><p class="small-note">Weather data by <a href="https://www.rainviewer.com/" target="_blank" rel="noopener">RainViewer</a> · podkład © OpenStreetMap · odświeżanie listy co 5 minut. Brak echa może oznaczać również brak pokrycia radarowego.</p></section>';}

