const strip=h=>{const d=document.createElement('div');d.innerHTML=h||'';return d.textContent||'';};
function sanitize(html){const doc=new DOMParser().parseFromString(html||'','text/html');doc.querySelectorAll('script,object,embed,form,style,link,meta,base').forEach(x=>x.remove());doc.querySelectorAll('*').forEach(el=>{[...el.attributes].forEach(a=>{if(/^on/i.test(a.name)||a.name==='srcdoc'||(/^(href|src|xlink:href|action)$/i.test(a.name)&&/^\s*(javascript|data|vbscript):/i.test(a.value)))el.removeAttribute(a.name);});if(el.tagName==='A'){try{const url=new URL(el.getAttribute('href'),cfg.original||'https://meteo-krosno.pl/');if(url.hostname==='meteo-krosno.pl')el.setAttribute('href',url.pathname+url.search+url.hash);else{el.setAttribute('target','_blank');el.setAttribute('rel','noopener');}}catch{}}if(el.tagName==='IFRAME'){const src=el.getAttribute('src')||'';if(!/^https:\/\//.test(src)){const p=doc.createElement('p'),a=doc.createElement('a');a.href=/^https?:/.test(src)?src:'#';a.textContent='Otwórz oryginalny wykres lub mapę';a.target='_blank';a.rel='noopener';p.append(a);el.replaceWith(p);}else{el.setAttribute('sandbox','allow-scripts allow-same-origin allow-popups');el.setAttribute('loading','lazy');el.setAttribute('title','Mapa lub wykres Meteo Krosno');}}});return doc.body.innerHTML;}
