function articleCard(p){const title=strip(p.title?.rendered),excerpt=strip(p.excerpt?.rendered).slice(0,165),d=p.date?.slice(0,10),url=new URL(p.link).pathname,img=p.thumbnail||(p.content?.rendered||'').match(/<img[^>]+src=["']([^"']+)["']/i)?.[1];return '<a class="article-card" href="'+esc(url)+'">'+(img&&/^https:/.test(img)?'<img src="'+esc(img)+'" alt="" loading="lazy"/>':'')+'<div class="article-body"><span class="article-date">'+(d?dateLabel(d)+' '+d.slice(0,4):'Archiwum')+'</span><h3>'+esc(title)+'</h3><p>'+esc(excerpt)+(excerpt.length>=165?'…':'')+'</p></div></a>';}
