async function original(path){main.innerHTML='<div class="loading">Pobieranie podstrony…</div>';const p=await loadArticles(path,1),item=p.items[0];if(!item){main.innerHTML=head('Podstrona Meteo Krosno','')+'<div class="empty">Nie udało się pobrać treści tej podstrony. <a class="btn" href="https://meteo-krosno.pl/'+esc(path)+'/">Otwórz oryginalną podstronę</a></div>';return;}document.title=strip(item.title.rendered)+' · Meteo Krosno';main.innerHTML='<div class="page-head"><a class="btn" href="/">Meteo Krosno</a><span class="pill">'+(/^\d{4}\//.test(path)?'Artykuł archiwalny':'Podstrona')+'</span></div>'+(p.fallback?'<div class="notice info">Treść z kopii pobranej 8 października 2026.</div>':'')+'<article class="prose"><div class="eyebrow">Meteo Krosno</div><h1>'+esc(strip(item.title.rendered))+'</h1>'+sanitize(item.content.rendered)+'</article>';}
async function render(){const path=location.pathname.replace(/^\/+|\/+$/g,'');try{if(!path||path==='strona-glowna')await home();else if(path==='prognoza')await forecast();else if(path==='meteorogram')await meteogram();else if(path==='sprawdzalnosc')await verification();else if(path==='miesiac-na-zywo')await monthLive();else if(path==='analizator')await atlas();else if(path==='tego-dnia')await history();else if(path==='mapy')maps();else if(path==='stacje'||path==='stacja-meteorologiczna')stations();else if(path==='przydatne-linki'){main.innerHTML=head('Przydatne linki','Zestaw źródeł zachowanych z Meteo Krosno.')+'<div class="link-grid">'+links.map(l=>tile(...l)).join('')+'</div>';}else if(/^page\/\d+$/.test(path))await articles('blog',+path.split('/')[1]);else if(path==='blog'||path.startsWith('category/')||path==='podsumowania')await articles(path==='podsumowania'?'category/podsumowania':path);else await original(path);}catch(e){main.innerHTML=head('Dane są chwilowo niedostępne','')+'<div class="empty">Odśwież stronę lub przejdź do <a href="https://meteo-krosno.pl/">obecnej witryny Meteo Krosno</a>.</div>';console.error(e);}}
