 const shell=document.createElement('div');shell.id='mk-dashboard';shell.innerHTML='<div class="mk-tabs" role="tablist" aria-label="Wybierz dział strony głównej"></div>';
 const defs=[['live','Na żywo','Pomiary, przebieg dnia i planowanie wyjścia'],['forecast','Prognoza','Najbliższe dni w modelu GFS'],['climate','Klimat','Historia dnia i podsumowanie miesiąca'],['articles','Artykuły','Publikacje z naszego archiwum'],['guide','Przewodnik','Jak czytać dane pogodowe']];
 const panels={};defs.forEach(([id,label,desc],i)=>{const btn=document.createElement('button');btn.type='button';btn.id='mk-tab-'+id;btn.setAttribute('role','tab');btn.setAttribute('aria-controls','mk-panel-'+id);btn.setAttribute('aria-selected',String(i===0));btn.tabIndex=i===0?0:-1;btn.textContent=label;shell.querySelector('.mk-tabs').append(btn);const p=document.createElement('section');p.id='mk-panel-'+id;p.className='mk-panel';p.setAttribute('role','tabpanel');p.setAttribute('aria-labelledby',btn.id);p.tabIndex=0;p.hidden=i!==0;panels[id]=p;shell.append(p);btn.onclick=()=>activate(id);btn.onkeydown=e=>{const idx=defs.findIndex(d=>d[0]===id);let next;if(e.key==='ArrowRight')next=(idx+1)%defs.length;if(e.key==='ArrowLeft')next=(idx+defs.length-1)%defs.length;if(e.key==='Home')next=0;if(e.key==='End')next=defs.length-1;if(next!==undefined){e.preventDefault();activate(defs[next][0]);document.getElementById('mk-tab-'+defs[next][0]).focus();}};});
 function activate(id){defs.forEach(([k])=>{panels[k].hidden=k!==id;const b=shell.querySelector('#mk-tab-'+k);b.setAttribute('aria-selected',String(k===id));b.tabIndex=k===id?0:-1;});}
 let group='live';children.forEach(el=>{const title=el.querySelector('h2')?.textContent||'';if(el.classList.contains('climate-strip')||el.classList.contains('month-home'))group='climate';if(title==='Najbliższe dni')group='forecast';if(el.classList.contains('lower-grid'))group='climate';if(title==='Z naszego archiwum')group='articles';if(el.id==='live-home'||el.classList.contains('grid-top')||el.classList.contains('walk-card'))panels.live.append(el);else panels[group].append(el);});
 const facts=document.createElement('div');facts.id='mk-facts';facts.className='mk-facts';panels.live.prepend(facts);
 const intro=document.createElement('div');intro.className='mk-section-intro';intro.innerHTML='<div><div class="eyebrow">Zaplanuj kolejne dni</div><h2>Prognoza pod ręką</h2><p>Wybierz dzień, aby sprawdzić jego przebieg. Szczegółowa tabela jest dostępna w pełnej prognozie.</p></div><a class="btn" href="/prognoza/">Prognoza godzinowa →</a>';panels.forecast.prepend(intro);
 const preview=document.createElement('div');preview.id='mk-forecast-preview';preview.innerHTML=chartCard(selected);panels.forecast.append(preview);
