 if(['temp','pressure','wind','snow'].includes(p.id)){const key=p.keys[0],fill=p.id==='pressure'?'#f5df26':p.id==='wind'?'#47b352':p.id==='snow'?'#b9defa':'#e6a1a1';segments(key).forEach(rs=>{if(rs.length>1){const base=p.id==='temp'?y(Math.max(lo,Math.min(hi,0))):yb;s+='<path clip-path="url(#mg-clip-'+p.id+')" d="M'+x(rs[0].time)+','+base+' L'+rs.map(r=>x(r.time)+','+y(r.v)).join(' L')+' L'+x(rs.at(-1).time)+','+base+'Z" fill="'+fill+'" opacity="'+(p.id==='temp'?'.28':'.78')+'"/>';}});}
 if(p.id==='cloud'){p.keys.forEach((key,ki)=>{segments(key).forEach(rs=>{if(rs.length>1)s+='<path clip-path="url(#mg-clip-cloud)" d="M'+x(rs[0].time)+','+yb+' L'+rs.map(r=>x(r.time)+','+y(r.v/12.5)).join(' L')+' L'+x(rs.at(-1).time)+','+yb+'Z" fill="'+['#ffffff','#929292','#41464d'][ki]+'" opacity=".75"/>';});});}
