async function mgExportPng(){
 const button=$('#mg-png'),status=$('#mg-png-status'),svg=$('#mg-svg');if(!svg||!button)return;
 const selectedHours=mgHours,selectedRun=G?.run,copy=svg.cloneNode(true),box=svg.viewBox.baseVal;
 let svgUrl=null,pngUrl=null;button.disabled=true;button.textContent='Zapisywanie…';if(status)status.textContent='Przygotowywanie obrazu PNG…';
 try{
  const width=box.width,height=box.height;if(!(width>0&&height>0))throw Error('Invalid chart size');
  copy.setAttribute('xmlns','http://www.w3.org/2000/svg');copy.setAttribute('width',String(width));copy.setAttribute('height',String(height));
  svgUrl=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(copy)],{type:'image/svg+xml;charset=utf-8'}));
  const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('Image loading failed'));image.src=svgUrl;});
  const canvas=document.createElement('canvas');canvas.width=Math.round(width*2);canvas.height=Math.round(height*2);const context=canvas.getContext('2d');if(!context)throw Error('Canvas unavailable');
  context.fillStyle='#fffdf4';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);
  const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('PNG encoding failed')),'image/png'));
  pngUrl=URL.createObjectURL(blob);const link=document.createElement('a'),stamp=valid(selectedRun)?new Date(selectedRun).toISOString().slice(0,13).replace(/[-:T]/g,'')+'UTC':'run';
  link.href=pngUrl;link.download='meteorogram-krosno-'+stamp+'-'+selectedHours+'h.png';document.body.append(link);link.click();link.remove();
  if(status)status.textContent='Gotowe — przygotowano PNG '+canvas.width+' × '+canvas.height+' px.';
 }catch(error){if(status)status.textContent='Nie udało się zapisać PNG. Spróbuj ponownie.';console.error('Meteorogram PNG export failed',error);}
 finally{if(svgUrl)URL.revokeObjectURL(svgUrl);if(pngUrl){const revoke=pngUrl;setTimeout(()=>URL.revokeObjectURL(revoke),60000);}button.disabled=false;button.textContent='Zapisz PNG';}
}
async function meteogram(){
 await Promise.all([loadGfs(),loadGfsRuns()]);const range=mgWindow(G?.rows||[],mgHours,G?.run);mgRows=range.rows.map(r=>({...r,fog:mgFogProbability(r)}));
 const fresh=G&&valid(G.run)&&Date.now()-G.run<=36*3600000;
 main.innerHTML=head('Meteorogram GFS · '+mgHours+' h','Godzinowa prognoza dla Krosna. Górna oś: UTC · dolna oś: czas polski (letni / zimowy).',G?'<span class="pill">Prognoza z '+runLabel(G.run)+'</span>':'')+warning()+runControl()+'<div class="toolbar mg-toolbar"><div class="segmented" aria-label="Zakres meteorogramu">'+[24,48,72,120].map(h=>'<button data-mg-hours="'+h+'" aria-pressed="'+(mgHours===h)+'">'+h+' h</button>').join('')+'</div><button class="btn" id="mg-refresh">Odśwież dane</button><button class="btn" id="mg-csv" '+(!mgRows.length?'disabled':'')+'>Pobierz dane</button><button class="btn" id="mg-png" '+(!mgRows.length?'disabled':'')+'>Zapisz PNG</button><span id="mg-png-status" class="small-note" role="status" aria-live="polite"></span><a class="btn" href="/prognoza/">Tabela prognozy →</a></div>'+
 (mgRows.length?'<div class="stats">'+stat('Zakres prognozy',mgHours+' h',dateShort(new Date(range.start).toISOString().slice(0,10))+' '+new Date(range.start).toISOString().slice(11,16)+' – '+dateShort(new Date(range.end).toISOString().slice(0,10))+' '+new Date(range.end).toISOString().slice(11,16)+' UTC')+stat('Temperatura',fmt(min(mgRows.map(r=>r.temp)))+' / '+fmt(max(mgRows.map(r=>r.temp)))+' °C','Minimum / maksimum dostępnych terminów')+stat('Suma opadu',fmt(sum(mgRows.map(r=>r.rain)))+' mm',mgRows.filter(r=>valid(r.rain)).length+' terminów z pomiarem opadu')+stat('Najsilniejszy poryw',fmt(max(mgRows.map(r=>r.gust)))+' m/s',gfsRun?'Wybrany przebieg archiwalny':fresh?'Bieżący dostępny przebieg':'Sprawdź wiek przebiegu powyżej')+'</div><p class="small-note">Dostępne '+mgRows.length+' z '+mgHours+' godzin. Zakres zaczyna się od pierwszego terminu pliku wybranego runu GFS (T+0), niezależnie od bieżącej godziny. Braki pozostają przerwami; brak danych nie oznacza zera. Na telefonie przesuń wykres poziomo.</p><section class="card mg-card"><div class="mg-scroll" tabindex="0" role="region" aria-label="Przewijany meteorogram GFS">'+mgSvg(mgRows,range.start,range.end)+'</div></section><section class="card mg-inspector"><label for="mg-time">Sprawdź termin prognozy</label><select id="mg-time">'+mgRows.map((r,i)=>'<option value="'+i+'">'+esc(r.date)+' UTC</option>').join('')+'</select><div id="mg-details" aria-live="polite">'+mgDetails(mgRows[0])+'</div></section><details class="card mg-table"><summary>Wszystkie dane godzinowe · '+mgRows.length+' terminów</summary><div class="table-wrap"><table><thead><tr>'+['Termin UTC','T2m °C','Punkt rosy °C','Opad mm/krok','Wiatr m/s','Porywy m/s','Kierunek °','MSLP hPa','Pokrywa cm','Chmury wysokie okt.','Chmury średnie okt.','Chmury niskie okt.','Mgła %','Podstawa m AGL','Źródło podstawy','Widzialność km','Rodzaj opadu'].map(v=>'<th>'+v+'</th>').join('')+'</tr></thead><tbody>'+mgRows.map(r=>'<tr><td>'+esc(r.date)+'</td>'+['temp','dew','rain','wind','gust','dir','pressure','snow','cloudHigh','cloudMid','cloudLow','fog'].map(k=>'<td>'+fmt(k.startsWith('cloud')?mgOktas(r[k]):r[k],['dir','fog'].includes(k)?0:1)+'</td>').join('')+'<td>'+fmt(mgCloudBase(r).height,0)+'</td><td>'+esc(mgCloudBase(r).source)+'</td><td>'+fmt(r.vis)+'</td><td>'+esc(r.type||'—')+'</td>'+'</tr>').join('')+'</tbody></table></div></details>':'<div class="empty">Brak terminów GFS w wybranym przedziale. Odśwież dane lub spróbuj ponownie później.</div>')+'<details class="card feature-section"><summary>Jak obliczamy prawdopodobieństwo mgły?</summary><p>Dla każdego terminu prognozy obliczamy szacunkową szansę mgły (widzialność poniżej 1 km). Uwzględniamy temperaturę T i punkt rosy Td na 2 m, wiatr na 10 m, noc w Krośnie, zachmurzenie oraz dostępną widzialność modelową. To autorska heurystyka, bez kalibracji statystycznej na lokalnych obserwacjach; procent jest orientacyjną oceną warunków sprzyjających mgle.</p><p>RH = 100 × exp[17,625 × Td / (243,04 + Td) − 17,625 × T / (243,04 + T)]. S = max(0, min(1, (RH − 75) / 25))². W = 0,15 + 0,85 × exp[−(wiatr / 3,5)²]. Wynik bazowy = 100 × S × (0,20 + 0,50 × W + 0,20 × N × C + 0,10 × L), gdzie wiatr jest w m/s, N wynosi 1 nocą i 0 za dnia, C = 1 − zachmurzenie ogólne / 100, L = zachmurzenie niskie / 100. Brak zachmurzenia pomija dany składnik.</p><p>Jeśli dostępna jest widzialność V w km: wynik = 0,55 × wynik bazowy + 0,45 × 100 × S / (1 + V²). Przy opadzie powyżej 0,1 mm/krok wynik mnożymy przez max(0,5, 1 − 0,15 × opad), aby ograniczyć mylenie pogorszonej widzialności w opadzie z mgłą. Wynik zaokrąglamy do pełnego procentu w zakresie 0–95%. Braki i nieprawidłowe dane podstawowe pozostają oznaczone kreską. Parametr przelicza się przy każdym odczycie prognozy, również po zmianie zakresu.</p><p class="small-note">Założenia fizyczne: <a href="https://www.weather.gov/safety/fog-radiation" target="_blank" rel="noopener">NWS — mgła radiacyjna</a>. Współczynniki są własne i nie stanowią wzoru NWS.</p></details><p class="small-note">Opad oznacza sumę w danym przedziale prognozy. Skala według najwyższego słupka: do 5 mm co 1 mm, do 10 mm co 2 mm, powyżej 10 mm do 25 mm co 5 mm. <span style="color:#dc2626">●</span> Czerwona kropka na szczycie słupka oznacza opad powyżej skali (ponad 25 mm/krok); dokładna wartość jest w podglądzie terminu i tabeli. Kolory: deszcz zielony, śnieg niebieski, opad marznący różowy, deszcz ze śniegiem turkusowy, nieokreślony szary. Pokrywa śnieżna w cm. Piętra chmur nakładają się na wspólnej osi 0–8 oktantów (100% = 8 okt.; nie sumujemy pięter). Mgła ma osobną prawą oś 0–100%. Nad zachmurzeniem: krótkie kreski podstawy/pułapu chmur i pomarańczowa linia widzialności (prawa oś w km). Obie osie wysokości i widzialności mają skalę nieliniową, aby uwidocznić niskie podstawy i słabą widzialność. Ciągłe kreski: pułap BKN/OVC z GFS. Przerywane: przybliżenie LCL = 125 × max(0, T − Td) m nad gruntem; nie jest to pomiar rzeczywistej podstawy ani prognoza wszystkich warstw. Odcień i szerokość kreski odpowiadają zachmurzeniu ogólnemu, ponieważ GFS nie podaje tu osobnych podstaw dla kolejnych progów pokrycia jak model UM w ICM. Żółte słupki: obliczane, szacunkowe prawdopodobieństwo mgły. Brak temperatury, punktu rosy lub wiatru oznacza brak wyniku, a nie 0%. Wiatr w m/s (× 3,6 = km/h). Ciśnienie zredukowane do poziomu morza. Prognoza modelowa nie jest ostrzeżeniem meteorologicznym.</p>';
 const stormInfo=document.createElement('details');stormInfo.className='card feature-section';stormInfo.innerHTML='<summary>Jak czytać potencjał burzowy?</summary><p>Białe kółko: warunki sprzyjające burzom. Żółte, pomarańczowe i czerwone: rosnący potencjał przy sygnale opadu lub konwekcji. Wskaźnik łączy CAPE, CIN, opad konwekcyjny, modelową odbiciowość i opad całkowity. To autorska heurystyka GFS, bez kalibracji statystycznej; nie określa liczby wyładowań ani prawdopodobieństwa. Brak danych jest oznaczony osobno.</p><p>Inspiracja sposobem prezentacji: <a href="https://www.meteo.pl/faq/how-should-the-information-about-thunderstorms-on-the-meteogram-be-interpreted?lang=en" target="_blank" rel="noopener">meteorogramy ICM</a>. Kolory na tej stronie odnoszą się do naszego wskaźnika GFS.</p>';main.append(stormInfo);
 bindRunControl(meteogram);$('#mg-png').onclick=mgExportPng;document.querySelectorAll('[data-mg-hours]').forEach(b=>b.onclick=()=>{mgHours=+b.dataset.mgHours;meteogram();});$('#mg-refresh').onclick=async()=>{gPromise=null;$('#mg-refresh').disabled=true;await meteogram();};$('#mg-csv').onclick=()=>download('meteorogram-krosno-'+mgHours+'h.csv',['Czas UTC;T2M;D2M;RRR;WSPD;GUST;WDIR;MSLP;SNOW cm;CH okt.;CM okt.;CL okt.;FOG szacunek obliczany %;Podstawa m AGL;Zrodlo podstawy;VIS km;Rodzaj opadu',...mgRows.map(r=>[r.date,r.temp,r.dew,r.rain,r.wind,r.gust,r.dir,r.pressure,r.snow,mgOktas(r.cloudHigh),mgOktas(r.cloudMid),mgOktas(r.cloudLow),r.fog,mgCloudBase(r).height,mgCloudBase(r).source,r.vis,r.type].map(csvCell).join(';'))].join('\r\n'));if($('#mg-time'))$('#mg-time').onchange=e=>{$('#mg-details').innerHTML=mgDetails(mgRows[+e.target.value]);};document.title='Meteorogram GFS '+mgHours+' h — Meteo Krosno';
}


