function miniSeries(rows,keys,labels,colors){
 const vals=rows.flatMap(r=>keys.map(k=>r[k])).filter(valid);if(!vals.length)return '<div class="empty">Brak pomiarów dla tego wykresu.</div>';
 const w=1000,h=260,L=50,R=22,T=22,B=40,lo=Math.floor(min(vals))-2,hi=Math.ceil(max(vals))+2,x=i=>L+i*(w-L-R)/Math.max(1,rows.length-1),y=v=>h-B-(v-lo)/(hi-lo)*(h-T-B);
 let s='<svg class="feature-chart" viewBox="0 0 '+w+' '+h+'" role="img" aria-label="'+esc(labels.join(' i '))+'">';for(let i=0;i<=4;i++){const v=lo+(hi-lo)*i/4;s+='<path d="M'+L+' '+y(v)+'H'+(w-R)+'" stroke="#dbe5ea"/><text x="'+(L-10)+'" y="'+(y(v)+4)+'" text-anchor="end">'+fmt(v,0)+'</text>';}
 keys.forEach((k,j)=>{let segment=[];const paint=()=>{if(segment.length)s+='<path d="M'+segment.map(p=>p.join(',')).join('L')+'" fill="none" stroke="'+colors[j]+'" stroke-width="2.5"'+(j?' stroke-dasharray="5 4"':'')+'/>';segment=[];};rows.forEach((r,i)=>{if(valid(r[k])){segment.push([x(i),y(r[k])]);s+='<circle cx="'+x(i)+'" cy="'+y(r[k])+'" r="3" fill="'+colors[j]+'"><title>'+esc(r.date)+' · '+labels[j]+': '+fmt(r[k])+' °C</title></circle>';}else paint();});paint();});
 rows.forEach((r,i)=>{if(i%Math.max(1,Math.ceil(rows.length/10))===0||i===rows.length-1)s+='<text x="'+x(i)+'" y="'+(h-12)+'" text-anchor="middle">'+esc(r.label||dateShort(r.date))+'</text>';});return s+'</svg><div class="chart-legend">'+labels.map((l,i)=>'<span><i style="background:'+colors[i]+'"></i>'+esc(l)+'</span>').join('')+'</div>';
}
function monthCards(m){const n=+m.ym.slice(5)-1;return '<div class="feature-metrics">'+[['Temperatura średnia',fmt(m.tm)+' °C','Odchylenie dla tych samych dni: '+signed(m.anomaly)+' °C',m.anomaly>0?'warm':'cold'],['Opad w zapisanych dniach',fmt(sum(m.rs.map(r=>r.rr)))+' mm',m.rs.filter(r=>valid(r.rr)).length+' / '+m.finished+' zakończonych dni z pomiarem','rain'],['Usłonecznienie',fmt(sum(m.rs.map(r=>r.sun)))+' h',m.rs.filter(r=>valid(r.sun)).length+' / '+m.finished+' zakończonych dni z pomiarem','sun']].map(([l,v,p,c])=>'<article class="feature-metric '+c+'"><small>'+l+'</small><strong>'+v+'</strong><p>'+p+'</p></article>').join('')+'</div>';}
function monthSummary(){const m=monthContext();return '<section class="month-home"><div class="section-head"><h2>Miesiąc na żywo</h2><a href="/miesiac-na-zywo/">Pełne podsumowanie →</a></div><p class="small-note">'+new Date(m.ym+'-15T12:00:00Z').toLocaleDateString('pl-PL',{month:'long',year:'numeric'})+' · ostatnia doba w archiwum: '+esc(m.last?.date||'brak danych z bieżącego miesiąca')+'</p>'+monthCards(m)+'</section>';}
async function monthLive(ym=today.slice(0,7)){
 await loadClimate();const m=monthContext(ym),all=climateRows(),latest=all.at(-1),n=+ym.slice(5)-1,monthName=new Date(ym+'-15T12:00:00Z').toLocaleDateString('pl-PL',{month:'long',year:'numeric'}),lag=m.finished-(m.last?+m.last.date.slice(8):0);
 main.innerHTML=head('Miesiąc na żywo','Bilans pomiarów IMGW Krosno · '+monthName,'<span class="pill green">Aktualizacja z archiwum</span>')+featureNav()+'<div class="toolbar"><label>Miesiąc<input type="month" id="month-pick" value="'+ym+'" max="'+today.slice(0,7)+'" min="'+(all[0]?.date.slice(0,7)||'1985-01')+'"></label><button class="btn primary" id="month-show">Pokaż miesiąc</button><button class="btn" id="month-refresh">Odśwież</button><button class="btn" id="month-csv">Pobierz dane</button></div>'+
 (C?.source.fallback?'<div class="notice">Źródło chwilowo niedostępne. Kopia archiwum z '+esc(C.source.savedAt)+'.</div>':'')+(lag>0?'<div class="notice info">Ostatnia dostępna doba tego miesiąca: '+esc(m.last?.date||'brak danych')+'. Liczba brakujących ostatnich zakończonych dób: '+lag+'. Dane dobowe mogą docierać z opóźnieniem.</div>':'')+monthCards(m)+
 '<div class="feature-two"><section class="card"><div class="eyebrow">Kompletność danych</div><h2>'+m.rs.length+' z '+m.finished+' zakończonych dób</h2><p class="small-note">Bieżącej, niezakończonej doby nie wliczamy do statystyk. Ostatni zapis w całym archiwum: '+esc(latest?.date||'—')+'.</p><div class="calendar-heat">'+m.rows.map(r=>'<span class="'+(r.date>=today?'future':valid(r.tm)?'known':'missing')+'" title="'+r.date+' · Tśr '+fmt(r.tm)+' °C">'+(+r.date.slice(8))+'</span>').join('')+'</div></section><section class="card"><div class="eyebrow">Norma 1991–2020 · pełny miesiąc</div><h2>Punkt odniesienia</h2><div class="norm-list"><span>Temperatura<strong>'+fmt(monthNorms.tm[n])+' °C</strong></span><span>Opad<strong>'+fmt(monthNorms.rr[n])+' mm</strong></span><span>Słońce<strong>'+fmt(monthNorms.sun[n])+' h</strong></span></div><p class="small-note">Anomalia temperatury u góry porównuje te same dni kalendarzowe, a nie część miesiąca z pełnym miesiącem. Braki opadu i słońca nie są zerami.</p></section></div>'+
 '<section class="card feature-section"><div class="card-title"><div><div class="eyebrow">Dzień po dniu</div><h2>Temperatura a klimat</h2></div><span class="pill">°C</span></div>'+miniSeries(m.rows.map(r=>({...r,normal:baselineDay(r.date,'tm')})),['tm','normal'],['Tśr obserwowana','Średnia tego dnia 1991–2020'],['#087f8c','#c98b28'])+'</section>'+
 '<div class="feature-metrics">'+stat('Najwyższa Tmax',fmt(max(m.rs.map(r=>r.tx)))+' °C',m.rs.filter(r=>r.tx===max(m.rs.map(r=>r.tx))).map(r=>dateShort(r.date)).join(', '))+stat('Najniższa Tmin',fmt(min(m.rs.map(r=>r.tn)))+' °C',m.rs.filter(r=>r.tn===min(m.rs.map(r=>r.tn))).map(r=>dateShort(r.date)).join(', '))+stat('Dni z przymrozkiem',String(m.rs.filter(r=>valid(r.tn)&&r.tn<0).length),'Tmin < 0°C · '+m.rs.filter(r=>valid(r.tn)).length+' dni z Tmin')+'</div>'+
 '<section class="card feature-section"><h2>Udział w normie całego miesiąca</h2>'+[['rr','Opad','mm'],['sun','Słońce','h']].map(([k,l,u])=>{const v=sum(m.rs.map(r=>r[k])),nn=m.rs.filter(r=>valid(r[k])).length,p=valid(v)?100*v/monthNorms[k][n]:null;return '<div class="norm-progress"><div><strong>'+l+'</strong><span>'+fmt(v)+' '+u+' / '+fmt(monthNorms[k][n])+' '+u+' · '+fmt(p,0)+'%</span></div><progress value="'+(p??0)+'" max="'+Math.max(100,p||0)+'" aria-label="'+l+' względem pełnej normy miesięcznej"></progress><small>'+nn+' z '+m.finished+' zakończonych dób. '+(nn<m.finished?'Suma niepełna — udział dotyczy tylko znanych wartości.':'Bieżący bilans, bez prognozowania końca miesiąca.')+'</small></div>';}).join('')+'</section>'+
 '<details class="card feature-section"><summary>Dane dobowe · '+m.rs.length+' zapisów</summary><div class="table-wrap"><table><thead><tr><th>Data</th><th>Tmax °C</th><th>Tmin °C</th><th>Tśr °C</th><th>Opad mm</th><th>Słońce h</th></tr></thead><tbody>'+m.rs.map(r=>'<tr><td>'+r.date+'</td>'+['tx','tn','tm','rr','sun'].map(k=>'<td>'+fmt(r[k])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div></details><p class="small-note">Podsumowanie obejmuje dostępne pomiary dobowe. Aktualizacja co 5 minut.</p>';
 $('#month-show').onclick=()=>{const v=$('#month-pick').value;if(/^\d{4}-\d{2}$/.test(v)&&v<=today.slice(0,7))monthLive(v);};$('#month-refresh').onclick=()=>{cPromise=null;monthLive(ym);};$('#month-csv').onclick=()=>download('krosno-'+ym+'.csv',['Data;Tmax;Tmin;Tsrednia;Opad;Slonce',...m.rs.map(r=>[r.date,r.tx,r.tn,r.tm,r.rr,r.sun].map(csvCell).join(';'))].join('\r\n'));document.title='Miesiąc na żywo · '+monthName+' · Meteo Krosno';
}
async function history(date=today){await historyLegacy(date);if(!C)return;const c=climateDay(date),rr=c.past.filter(r=>valid(r.rr)).sort((a,b)=>b.rr-a.rr)[0],sun=c.past.filter(r=>valid(r.sun)).sort((a,b)=>b.sun-a.sun)[0];main.querySelector('.page-head').insertAdjacentHTML('afterend',featureNav());main.querySelector('.toolbar').insertAdjacentHTML('afterend','<div class="feature-metrics">'+stat('Największy opad',fmt(rr?.rr)+' mm',rr?.date.slice(0,4)||'brak danych')+stat('Najwięcej słońca',fmt(sun?.sun)+' h',sun?.date.slice(0,4)||'brak danych')+stat('Częstość przymrozku',fmt(c.past.some(r=>valid(r.tn))?c.past.filter(r=>valid(r.tn)&&r.tn<0).length/c.past.filter(r=>valid(r.tn)).length*100:null,0)+'%','Wśród '+c.past.filter(r=>valid(r.tn)).length+' lat z pomiarem Tmin')+'</div><section class="card feature-section"><div class="eyebrow">Ten sam dzień w kolejnych latach</div><h2>Jak zmieniała się temperatura?</h2>'+miniSeries(c.past.map(r=>({...r,label:r.date.slice(0,4)})),['tx','tn'],['Tmax','Tmin'],['#d45b4d','#1687b1'])+'</section>');document.title=dateLabel(date)+' w historii · Meteo Krosno';}
