function paintStationMap(){if(!$('#station-list'))return;const units={temp:'°C',rain:'mm',wind:'km/h'},labels={temp:'Temperatura',rain:'Opad dzisiaj',wind:'Wiatr'};$('#station-list').innerHTML=stationPoints.map(p=>{const s=liveData?.stations?.find(s=>s.id===p.id),ts=s?.timestamps?.[mapMetric],fresh=s?.available&&!s?.fallback&&ts&&Math.abs(Date.now()/1000-ts)<=900,v=s?.[mapMetric],value=valid(v)?fmt(v)+' '+units[mapMetric]:'—',old=p.id==='imgw'?'Archiwum dobowe':fresh?'Świeży pomiar':'Brak świeżego pomiaru';const mark=stationMarkers[p.id];if(mark){mark.setIcon(window.L.divIcon({className:'station-pin-wrap',html:'<div class="station-pin '+(fresh?'fresh':'old')+'">'+(fresh?esc(value):esc(p.code))+'</div>',iconSize:[116,36],iconAnchor:[58,18]}));mark.bindPopup('<strong>'+esc(p.name)+'</strong><p>'+labels[mapMetric]+': '+esc(p.id==='imgw'?'Dane dobowe w archiwum':value)+'</p><small>'+esc(old)+' · położenie orientacyjne</small><p><a href="'+p.url+'">Otwórz dane stacji</a></p>');}return '<article class="station-map-card"><div class="card-top"><span class="station-label">'+p.code+'</span><span class="pill '+(fresh?'green':'')+'">'+old+'</span></div><h2>'+p.name+'</h2><strong class="station-map-value">'+(p.id==='imgw'?'IMGW':value)+'</strong><p class="small-note">'+(p.id==='imgw'?'Stacja referencyjna · klimat i historia.':labels[mapMetric]+' · '+(ts?liveTime(ts):'brak czasu pomiaru')+(fresh?'':' · wartość może być nieaktualna'))+'</p><div class="toolbar"><button class="btn" data-focus-station="'+p.id+'">Pokaż na mapie</button><a class="btn" href="'+p.url+'" '+(p.url.startsWith('http')?'target="_blank" rel="noopener"':'')+'>Pomiary →</a></div></article>';}).join('');document.querySelectorAll('[data-focus-station]').forEach(b=>b.onclick=()=>{const p=stationPoints.find(x=>x.id===b.dataset.focusStation);if(stationMap){stationMap.setView([p.lat,p.lon],13);stationMarkers[p.id].openPopup();$('#local-station-map').scrollIntoView({block:'center',behavior:'smooth'});}});}
async function stations(){main.innerHTML=head('Mapa lokalnych stacji','Mikroklimat Krosna i okolic · pomiary naszych stacji.')+featureNav()+'<section class="card feature-section"><div class="card-title"><div><div class="eyebrow">Sieć obserwacyjna</div><h2>Pogoda blisko Ciebie</h2></div><span class="pill green">Odświeżanie co minutę</span></div><div class="toolbar"><div class="segmented" aria-label="Parametr na mapie">'+[['temp','Temperatura'],['rain','Opad'],['wind','Wiatr']].map(([k,l])=>'<button data-map-metric="'+k+'" aria-pressed="'+(mapMetric===k)+'">'+l+'</button>').join('')+'</div><button id="map-reset" class="btn">Pokaż wszystkie stacje</button></div><div id="local-station-map" class="local-station-map" aria-label="Interaktywna mapa lokalnych stacji"><p class="empty">Ładowanie mapy…</p></div><p class="small-note">Znaczniki wskazują orientacyjne położenie miejscowości lub dzielnicy, nie dokładną lokalizację czujników. Zielony: pomiar do 15 minut. Szary: dane starsze lub archiwum. Wiatr w km/h; opad od początku lokalnej doby stacji.</p></section><div id="station-list" class="station-map-list"></div>';
 document.querySelectorAll('[data-map-metric]').forEach(b=>b.onclick=()=>{mapMetric=b.dataset.mapMetric;document.querySelectorAll('[data-map-metric]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));paintStationMap();});$('#map-reset').onclick=()=>stationMap?.fitBounds(stationPoints.map(p=>[p.lat,p.lon]),{padding:[45,45]});paintStationMap();await refreshLive();
 try{const L=await loadLeaflet();$('#local-station-map').innerHTML='';stationMap=L.map('local-station-map',{scrollWheelZoom:false});L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(stationMap);stationPoints.forEach(p=>{stationMarkers[p.id]=L.marker([p.lat,p.lon],{title:p.name,alt:p.name}).addTo(stationMap);});stationMap.fitBounds(stationPoints.map(p=>[p.lat,p.lon]),{padding:[60,60]});paintStationMap();}catch{$('#local-station-map').innerHTML='<div class="empty">Nie udało się wczytać podkładu mapy. Pomiary i odnośniki stacji są dostępne poniżej.</div>';}document.title='Mapa lokalnych stacji · Meteo Krosno';}
let verifyStation='turaszowka',verifyDays=30;
async function verification(){await loadGfs();main.innerHTML=head('Sprawdzalność prognoz','Model GFS a rzeczywiste pomiary temperatury naszych stacji.')+featureNav()+'<div class="toolbar"><label>Stacja odniesienia<select id="verify-station"><option value="turaszowka" '+(verifyStation==='turaszowka'?'selected':'')+'>Krosno – Turaszówka</option><option value="lesniowka" '+(verifyStation==='lesniowka'?'selected':'')+'>Leśniówka</option></select></label><label>Okres<select id="verify-days">'+[7,30,90].map(d=>'<option value="'+d+'" '+(verifyDays===d?'selected':'')+'>Ostatnie '+d+' dni</option>').join('')+'</select></label><button class="btn" id="verify-refresh">Odśwież</button></div><div id="verify-results" aria-live="polite" class="loading">Ładowanie porównań…</div>';
 $('#verify-station').onchange=e=>{verifyStation=e.target.value;verification();};$('#verify-days').onchange=e=>{verifyDays=+e.target.value;verification();};$('#verify-refresh').onclick=()=>verification();
 try{const res=await fetch(api('verification','?station='+verifyStation+'&days='+verifyDays),{cache:'no-store'});if(!res.ok)throw Error();const v=await res.json();$('#verify-results').className='';$('#verify-results').innerHTML='<div class="notice info">'+(v.pairs.length?'Wyniki dotyczą wyłącznie dostępnych par prognoza–pomiar.':'Archiwum zostało uruchomione. Zbieramy prognozy i pomiary — pierwsze wyniki pojawią się po upływie prognozowanych terminów.')+'</div><div class="stats">'+stat('Zapisane przebiegi GFS',String(v.runs),v.started?'Archiwizacja od '+new Date(v.started*1000).toLocaleDateString('pl-PL'):'Oczekiwanie na świeży GFS')+stat('Godziny z pomiarem',String(v.observations),'Wybrana stacja · przechowywanie do 90 dni')+stat('Pary w wybranym okresie',String(v.pairs.length),'Maks. jedna para na godzinę i przedział wyprzedzenia')+stat('Następny zbiór',v.nextCollection?new Date(v.nextCollection*1000).toLocaleTimeString('pl-PL',{timeZone:'Europe/Warsaw',hour:'2-digit',minute:'2-digit'}):'—','Czas polski')+'</div><div class="feature-metrics">'+v.stats.map(s=>'<section class="card verify-card"><div class="eyebrow">Wyprzedzenie '+s.bin+' h</div><h2>'+fmt(s.mae)+' <small>°C</small></h2><p>Średni błąd bezwzględny · MAE</p><dl><div><dt>RMSE</dt><dd>'+fmt(s.rmse)+' °C</dd></div><div><dt>Obciążenie</dt><dd>'+signed(s.bias)+' °C</dd></div><div><dt>Błąd ≤ 2°C</dt><dd>'+fmt(s.within2,0)+'%</dd></div><div><dt>Liczba porównań</dt><dd>'+s.n+'</dd></div></dl>'+(!s.n?'<small>Oczekiwanie na dane</small>':s.n<30?'<small>Mała próba — wynik wstępny</small>':'')+'</section>').join('')+'</div>'+ (v.pairs.length?'<section class="card feature-section"><div class="card-title"><h2>Ostatnie porównania</h2><button id="verify-csv" class="btn">Pobierz dane</button></div><div class="table-wrap"><table><thead><tr><th>Termin UTC</th><th>Prognoza z UTC</th><th>Wyprzedzenie</th><th>GFS °C</th><th>Pomiar °C</th><th>Błąd °C</th></tr></thead><tbody>'+v.pairs.slice(0,100).map(p=>'<tr><td>'+new Date(p.time).toISOString().slice(0,16).replace('T',' ')+'</td><td>'+new Date(p.run*1000).toISOString().slice(0,16).replace('T',' ')+'</td><td>'+fmt(p.lead,0)+' h</td><td>'+fmt(p.forecast)+'</td><td>'+fmt(p.observed)+'</td><td>'+signed(p.error)+'</td></tr>').join('')+'</tbody></table></div></section>':'')+'<section class="card feature-section"><div class="eyebrow">Przejrzysta metodologia</div><h2>Co dokładnie sprawdzamy?</h2><p>Temperaturę GFS dla Krosna porównujemy z temperaturą wybranej stacji Ecowitt. Pomiar musi przypadać nie dalej niż 15 minut od pełnej godziny UTC. Zachowujemy najbliższy pomiar i najnowszy dostępny run w każdym przedziale wyprzedzenia.</p><p>Prognoza musi być zapisana co najmniej 6 godzin przed terminem. Dane starsze, zastępcze i brakujące są pomijane. Znak dodatni błędu oznacza, że model prognozował za ciepło.</p><p class="small-note">MAE: średnia wielkość błędu. RMSE mocniej uwzględnia duże pomyłki. Obciążenie: średnia prognoza minus pomiar. Różnice obejmują też lokalny mikroklimat i odległość stacji od punktu GFS — szczególnie w Leśniówce. To nie jest oficjalna ocena modelu przez IMGW.</p><p class="small-note">Porównania uzupełniamy cyklicznie, gdy dostępne są prognozy i odpowiadające im pomiary. Niepełne dane są pomijane.</p></section>';
 if($('#verify-csv'))$('#verify-csv').onclick=()=>download('sprawdzalnosc-gfs-'+verifyStation+'.csv',['Termin UTC;Prognoza z UTC;Wyprzedzenie h;GFS C;Pomiar C;Blad C;Czas pomiaru UTC',...v.pairs.map(p=>[new Date(p.time).toISOString(),new Date(p.run*1000).toISOString(),p.lead,p.forecast,p.observed,p.error,new Date(p.observedAt).toISOString()].map(csvCell).join(';'))].join('\r\n'));}catch{$('#verify-results').innerHTML='<div class="notice">Nie udało się pobrać wyników. Użyj przycisku Odśwież.</div>';}document.title='Sprawdzalność prognoz GFS · Meteo Krosno';}
